//! Initial source only; global declarations remain genuine uncompiled CODE input.
pub const CASES:&[&str]=&["core_and_maps","bits_and_allow","exempt_index"];
pub fn files(case:&str)->Option<Vec<(&'static str,Vec<u8>)>>{if !CASES.contains(&case){return None}let mut files=vec![("p.dme",b"#include \"code/probe.dm\"\n".to_vec()),("code/probe.dm",b"/proc/probe()\n    return 1\n".to_vec()),("code/unit_tests/quiet.dm",b"// genuine selected unit-test source without sites\n".to_vec()),("tools/ci/lint_scopes.toml",b"[lint.\"sys/fields\"]\n".to_vec()),("code/declared.dm",b"OM_FIELD(/obj/machinery, on, 0, CHANNEL)\n/obj/machinery\n    var/on\n".to_vec())];match case{
"core_and_maps"=>{files.push(("code/raw.dm",b"/obj/machinery/proc/raw()\n    on=1\n    if(stat)\n        return inoperable()\n".to_vec()));files.push(("maps/raw.dm",b"/obj/machinery/proc/map_raw()\n    on=2\n    is_operational()\n".to_vec()));},
"bits_and_allow"=>{files.push(("code/raw.dm",b"/obj/machinery/proc/raw()\n    stat_add(NOPOWER)\n    inoperable() // ALLOW(sys_stat_helper): this exact source fixture retains the original helper\n    on=1 // ALLOW(sys_field_write): this exact source fixture retains the original field write\n    stat_remove(BROKEN)\n".to_vec()));files.push(("code/modules/unit_tests/raw.dm",b"/obj/machinery/proc/raw_test()\n    stat_add(NOPOWER)\n    on=2\n".to_vec()));},
"exempt_index"=>{files[3].1=b"[lint.\"sys/fields\"]\nexempt_files=[\"code/declared.dm\"]\n".to_vec();files.push(("maps/raw.dm",b"/obj/machinery/proc/raw()\n    on=3\n".to_vec()));},_=>return None}Some(files)}
